export function isValidHeaderName(value: unknown) {
  if (typeof value !== 'string') {
    return false
  }

  if (value.length === 0) {
    return false
  }

  for (let i = 0; i < value.length; i++) {
    const character = value.charCodeAt(i)

    if (character > 0x7f || !isToken(character)) {
      return false
    }
  }

  return true
}

function isToken(value: string | number): boolean {
  return ![
    0x7f,
    0x20,
    '(',
    ')',
    '<',
    '>',
    '@',
    ',',
    ';',
    ':',
    '\\',
    '"',
    '/',
    '[',
    ']',
    '?',
    '=',
    '{',
    '}',
  ].includes(value)
}
","/**
 * Validate the given header value.
 * @see https://fetch.spec.whatwg.org/#header-value
 */
export function isValidHeaderValue(value: unknown): boolean {
  if (typeof value !== 'string') {
    return false
  }

  if (value.trim() !== value) {
    return false
  }

  for (let i = 0; i < value.length; i++) {
    const character = value.charCodeAt(i)

    if (
      // NUL.
      character === 0x00 ||
      // HTTP newline bytes.
      character === 0x0a ||
      character === 0x0d
    ) {
      return false
    }
  }

  return true
}
