import { it } from 'vitest'
import { writeFileSync } from 'node:fs'
import { Hono } from './hono'
import { setCookie } from './helper/cookie'

const results: Record<string, string[]> = {}

it('B: c.res touched + c.header cookie + raw Response', async () => {
  const app = new Hono()
  app.use(async (c, next) => {
    c.res.headers.set('X-Something', 'true')
    c.header('Set-Cookie', 'mw=1; Path=/', { append: true })
    await next()
  })
  app.get('/', () => {
    const res = new Response('ok')
    res.headers.append('set-cookie', 'handler=1; Path=/; HttpOnly')
    return res
  })
  results['B'] = (await app.request('/')).headers.getSetCookie()
})

it('A: setCookie before next + raw Response', async () => {
  const app = new Hono()
  app.use(async (c, next) => {
    setCookie(c, 'mw', '1')
    await next()
  })
  app.get('/', () => {
    const res = new Response('ok')
    res.headers.append('set-cookie', 'handler=1; Path=/; HttpOnly')
    return res
  })
  results['A'] = (await app.request('/')).headers.getSetCookie()
})

it('text: c.res cookie + c.text()', async () => {
  const app = new Hono()
  app.use(async (c, next) => {
    c.res.headers.append('set-cookie', 'mw=1; Path=/')
    await next()
  })
  app.get('/', (c) => c.text('Hi'))
  results['text'] = (await app.request('/')).headers.getSetCookie()
})

it('json: c.res cookie + c.json()', async () => {
  const app = new Hono()
  app.use(async (c, next) => {
    c.res.headers.append('set-cookie', 'mw=1; Path=/')
    await next()
  })
  app.get('/', (c) => c.json({ ok: true }))
  results['json'] = (await app.request('/')).headers.getSetCookie()
  writeFileSync('/tmp/setcookie-results.json', JSON.stringify(results, null, 2))
})
